package com.wizzadrds.theworldremembers.chronicle;
import net.minecraft.client.gui.GuiGraphics; import net.minecraft.client.gui.screens.Screen; import net.minecraft.network.chat.Component; import java.util.*;
public final class ChronicleScreen extends Screen{private final List<List<String>> pages;private int page;public ChronicleScreen(String encoded){super(Component.literal("The World Remembers — Chronicles"));pages=parse(encoded);}
private static List<List<String>> parse(String raw){var out=new ArrayList<List<String>>();var current=new ArrayList<String>();for(String line:raw.split("\\n",-1)){if(line.startsWith("---")&&line.endsWith("---")){out.add(current);current=new ArrayList<>();}else current.add(line);}out.add(current);while(out.size()<5)out.add(new ArrayList<>());return out;}
@Override protected void init(){page=0;}
@Override public void render(GuiGraphics g,int mouseX,int mouseY,float delta){renderBackground(g,mouseX,mouseY,delta);g.drawCenteredString(font,title,getWidth()/2,18,0xFFFFFF);String[] names={"Timeline","People","Relationships","Families","Villages"};for(int i=0;i<names.length;i++)g.drawString(font,(i==page?"> ":"")+names[i],20+i*105,42,i==page?0xFFFF55:0xAAAAAA);var rows=pages.get(Math.min(page,pages.size()-1));int y=64;for(int i=0;i<Math.min(rows.size(),20);i++){String s=rows.get(i);if(s.length()>110)s=s.substring(0,107)+"...";g.drawString(font,s,24,y,0xE0E0E0);y+=12;}g.drawString(font,"←/→ change section · Esc close",24,getHeight()-24,0x888888);}
@Override public boolean keyPressed(int keyCode,int scanCode,int modifiers){if(keyCode==263){page=(page+4)%5;return true;}if(keyCode==262){page=(page+1)%5;return true;}return super.keyPressed(keyCode,scanCode,modifiers);}}
